window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-251bd16785b3f545"]={"versions": [{"id": "FIG-251bd16785b3f545", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponenten- und Timing-Diagramm im Kontext der AUTOSAR Adaptive Platform Timing Extensions. Das Diagramm spezifiziert eine Latenzanforderung (<code>LatencyTimingConstraint</code> bzw. <code>Maximum Latency</code>) über eine Softwarekomponente hinweg zwischen einem eingehenden und einem ausgehenden Service-Port.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application Software Component (<code>Swc1</code>)</strong>: Hellblau hinterlegter Komponentenblock, der die Anwendungslogik kapselt.\n</li><li><strong>Required Port</strong>: Kleines quadratisches Port-Symbol am linken Rand der Komponente <code>Swc1</code> zur Aufnahme externer Servicedaten.\n</li><li><strong>Provided Port</strong>: Kleines quadratisches Port-Symbol am rechten Rand der Komponente <code>Swc1</code> zur Bereitstellung von Services.\n</li><li><strong>Virtuelle Verbindungen (gestrichelte Linien)</strong>: Kennzeichnen die während Service Discovery und Subscription etablierten virtuellen Kommunikationsbeziehungen (<code>Virtual connection created/established during service discovery and subscription</code>).\n</li><li><strong>Legende</strong>: Erläutert die graphischen Notationen für gestrichelte Verbindungen, Service Ports (Quadrate) und Adaptive Application Software Components (Rechtecke).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ein eintreffendes Ereignis bzw. ein Datenempfang am <code>Required Port</code> initiiert die interne Verarbeitung innerhalb von <code>Swc1</code>. Die resultierende Bereitstellung bzw. das Senden am <code>Provided Port</code> muss innerhalb des definierten Zeitfensters abgeschlossen sein. Das Latenzintervall ist durch vertikale Hilfslinien und einen doppelseitigen horizontalen Pfeil mit der Bedingung <code>Maximum Latency = 2ms</code> zwischen dem Eingangs- und dem Ausgangs-Port definiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung illustriert eine normative Randbedingung für das Timing-Modell: Eine Latenzanforderung an eine adaptive Softwarekomponente begrenzt die maximale Verarbeitungszeit zwischen Eingangsereignis am <code>Required Port</code> und Ausgangsereignis am <code>Provided Port</code> auf 2 ms. Entwickler müssen sicherstellen, dass die Task-Ausführung, Scheduling-Latenzen und komponenteneigene Verarbeitungszeiten auf der Adaptive Platform diese Obergrenze deterministisch einhalten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e4aa14794fb48f0a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Komponenten- und Timing-Diagramm im Kontext der AUTOSAR Adaptive Platform Timing Extensions. Das Diagramm spezifiziert eine Latenzanforderung (<code>LatencyTimingConstraint</code> bzw. <code>Maximum Latency</code>) über eine Softwarekomponente hinweg zwischen einem eingehenden und einem ausgehenden Service-Port.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application Software Component (<code>Swc1</code>)</strong>: Hellblau hinterlegter Komponentenblock, der die Anwendungslogik kapselt.\n</li><li><strong>Required Port</strong>: Kleines quadratisches Port-Symbol am linken Rand der Komponente <code>Swc1</code> zur Aufnahme externer Servicedaten.\n</li><li><strong>Provided Port</strong>: Kleines quadratisches Port-Symbol am rechten Rand der Komponente <code>Swc1</code> zur Bereitstellung von Services.\n</li><li><strong>Virtuelle Verbindungen (gestrichelte Linien)</strong>: Kennzeichnen die während Service Discovery und Subscription etablierten virtuellen Kommunikationsbeziehungen (<code>Virtual connection created/established during service discovery and subscription</code>).\n</li><li><strong>Legende</strong>: Erläutert die graphischen Notationen für gestrichelte Verbindungen, Service Ports (Quadrate) und Adaptive Application Software Components (Rechtecke).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ein eintreffendes Ereignis bzw. ein Datenempfang am <code>Required Port</code> initiiert die interne Verarbeitung innerhalb von <code>Swc1</code>. Die resultierende Bereitstellung bzw. das Senden am <code>Provided Port</code> muss innerhalb des definierten Zeitfensters abgeschlossen sein. Das Latenzintervall ist durch vertikale Hilfslinien und einen doppelseitigen horizontalen Pfeil mit der Bedingung <code>Maximum Latency = 2ms</code> zwischen dem Eingangs- und dem Ausgangs-Port definiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Abbildung illustriert eine normative Randbedingung für das Timing-Modell: Eine Latenzanforderung an eine adaptive Softwarekomponente begrenzt die maximale Verarbeitungszeit zwischen Eingangsereignis am <code>Required Port</code> und Ausgangsereignis am <code>Provided Port</code> auf 2 ms. Entwickler müssen sicherstellen, dass die Task-Ausführung, Scheduling-Latenzen und komponenteneigene Verarbeitungszeiten auf der Adaptive Platform diese Obergrenze deterministisch einhalten.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-251bd16785b3f545", "to": "FIG-e4aa14794fb48f0a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
